<?php/** * Description of User * * @author Suharshana DsW * @web www.nysc.lk */class Fedaration {    public $id;    public $name;    public $address;    public $mobile_number;    public $office_number;    public $email;    public $queue;    public function __construct($id) {        if ($id) {            $query = "SELECT * FROM `fedaration` WHERE `id`=" . $id;            $db = new Database();            $result = mysqli_fetch_array($db->readQuery($query));            $this->id = $result['id'];            $this->name = $result['name'];            $this->address = $result['address'];            $this->mobile_number = $result['mobile_number'];            $this->office_number = $result['office_number'];            $this->email = $result['email'];            $this->queue = $result['queue'];            return $result;        }    }    public function create() {        $query = "INSERT INTO `fedaration` (`name`,`address`,`mobile_number`,`office_number`,`email`,`queue`) VALUES  ('"                . $this->name . "', '"                . $this->address . "', '"                . $this->mobile_number . "', '"                . $this->office_number . "', '"                . $this->email . "', '"                . $this->queue . "')";        $db = new Database();        $result = $db->readQuery($query);        if ($result) {            return TRUE;        } else {            return FALSE;        }    }    public function all() {        $query = "SELECT * FROM `fedaration`";        $db = new Database();        $result = $db->readQuery($query);        $array_res = array();        while ($row = mysqli_fetch_array($result)) {            array_push($array_res, $row);        }        return $array_res;    }    public function update() {        $query = "UPDATE  `fedaration` SET "                . "`name` ='" . $this->name . "',"                . "`address` ='" . $this->address . "',"                . "`mobile_number` ='" . $this->mobile_number . "',"                . "`office_number` ='" . $this->office_number . "',"                . "`email` ='" . $this->email . "'"                . "WHERE `id` = '" . $this->id . "'";        $db = new Database();        $result = $db->readQuery($query);        if ($result) {            return $this->__construct($this->id);        } else {            return FALSE;        }    }    public function delete() {        $query = 'DELETE FROM `fedaration` WHERE id="' . $this->id . '"';        $db = new Database();        return $db->readQuery($query);    }}